import { phase } from '/tmp/probe/p.mjs';

export function fence(code, lang='javascript') {
  return '```' + lang + '\n' + code + '\n```';
}
// One executable invocation, many fenced blocks. Returns array of inner <code> bodies.
export function batch(cases, lang='javascript') {
  const doc = cases.map(c => fence(c, lang)).join('\n\n');
  const out = phase('e', doc);
  // split on the codehilite div boundaries
  const parts = out.split('<div class="codehilite"><pre><span></span><code>');
  const bodies = [];
  for (let i=1;i<parts.length;i++){
    let b = parts[i];
    const j = b.indexOf('</code></pre></div>');
    bodies.push(j>=0 ? b.slice(0,j) : b);
  }
  return { bodies, raw: out };
}
export function show(cases, lang='javascript') {
  const {bodies, raw} = batch(cases, lang);
  if (bodies.length !== cases.length) {
    console.log('!!! COUNT MISMATCH expected', cases.length, 'got', bodies.length);
    console.log('RAW:', JSON.stringify(raw));
    return;
  }
  for (let i=0;i<cases.length;i++) console.log(JSON.stringify(cases[i]) + '  ->  ' + JSON.stringify(bodies[i]));
}
// single-case, isolated (safer for weird inputs)
export function one(code, lang='javascript') {
  const out = phase('e', fence(code, lang));
  return out;
}
